"""Writes THIRD_PARTY_NOTICES.md from the app's library list plus the components it doesn't name.

Usage (from the repository root): python3 tools/third_party_notices.py .
"""
import re, sys
root = sys.argv[1]
lib = open(root + '/ZalithLauncher/src/main/java/com/movtery/zalithlauncher/library/_Libraries.kt', encoding='utf-8').read()
consts = dict(re.findall(r'private const val (\w+) = "([^"]*)"', lib))
consts['LICENSE_APACHE_2'] = 'Apache License 2.0'
def val(tok):
    tok = tok.strip()
    if tok == 'null': return None
    if tok.startswith('"'): return tok.strip('"')
    m = re.match(r'License\((\w+|"[^"]*"),', tok)
    if m: return val(m.group(1))
    return consts.get(tok, tok)
rows = []
for m in re.finditer(r'LibraryInfo\((.*)\),?\s*$', lib, re.M):
    args = re.findall(r'License\([^)]*\)|"[^"]*"|\w+', m.group(1))
    name, cp, lic, url = (val(a) for a in args[:4])
    rows.append((name, cp, lic, url))
extra = [
    ("AndroidX (Compose, Material 3, Lifecycle, Activity, Room, Hilt, Core, DocumentFile, SplashScreen)", "Copyright © The Android Open Source Project", "Apache License 2.0", "https://developer.android.com/jetpack/androidx"),
    ("Dagger / Hilt", "Copyright © The Dagger Authors", "Apache License 2.0", "https://github.com/google/dagger"),
    ("Material Components for Android", "Copyright © Google LLC", "Apache License 2.0", "https://github.com/material-components/material-components-android"),
    ("kotlinx.serialization", "Copyright © 2017-2024 JetBrains s.r.o.", "Apache License 2.0", "https://github.com/Kotlin/kotlinx.serialization"),
    ("Ktor server", "Copyright © 2000-2023 JetBrains s.r.o.", "Apache License 2.0", "https://ktor.io"),
    ("MaterialKolor", "Copyright © Jordon de Hoog", "MIT License", "https://github.com/jordond/materialkolor"),
    ("compose-richtext", "Copyright © Halil Ozercan", "Apache License 2.0", "https://github.com/halilozercan/compose-richtext"),
    ("Zip4j", "Copyright © Srikanth Reddy Lingala", "Apache License 2.0", "https://github.com/srikanth-lingala/zip4j"),
    ("MiniDNS", "Copyright © Florian Schmaus and contributors", "Apache License 2.0 / LGPL-2.1+ / WTFPL (triple-licensed)", "https://github.com/MiniDNS/minidns"),
    ("toml4j", "Copyright © Moandji Ezana", "MIT License", "https://github.com/mwanji/toml4j"),
    ("SQLCipher for Android", "Copyright © Zetetic LLC", "BSD-style licence (see project)", "https://github.com/sqlcipher/sqlcipher-android"),
    ("LunarCalendar", None, "See project", "https://github.com/xhinliang/LunarCalendar"),
    ("SPIRV-Cross", "Copyright © The Khronos Group Inc. and contributors", "Apache License 2.0", "https://github.com/KhronosGroup/SPIRV-Cross"),
    ("OpenAL Soft", "Copyright © Chris Robinson and contributors", "LGPL-2.0 (or later)", "https://github.com/kcat/openal-soft"),
]
have = {r[0].lower() for r in rows}
out = []
out.append("# Third-party notices\n")
out.append("Voxelium for Android is free software under the GNU General Public License v3.0 (see `LICENSE`), with Zalith Launcher 2's additional terms under GPLv3 §7 (see `NOTICE.md`). It contains the third-party components below, each under its own licence. The app shows the same library list, with the licence texts it bundles, under Settings → About → Credits and licences.\n")
out.append("This file lists the components and where their licences can be found. It is generated by `tools/third_party_notices.py` from `ZalithLauncher/src/main/java/com/movtery/zalithlauncher/library/_Libraries.kt` (the in-app list) plus the dependencies that list does not name.\n")
out.append("## Built on\n")
out.append("- **Zalith Launcher 2**: Copyright © 2025 MovTery and contributors. GPL-3.0. https://github.com/ZalithLauncher/ZalithLauncher2")
out.append("- **PojavLauncher** (the launch backend under `ZalithLauncher/src/main/jni`): LGPL-3.0 / GPL-3.0. https://github.com/PojavLauncherTeam/PojavLauncher")
out.append("- **Fold Craft Launcher** and **Hello Minecraft! Launcher**: code from both is incorporated in Zalith Launcher 2. GPL-3.0. https://github.com/FCL-Team/FoldCraftLauncher, https://github.com/HMCL-dev/HMCL\n")
out.append("## Bundled runtimes and native components\n")
out.append("- **OpenJDK** runtimes 8, 17, 21 and 25 (`assets/runtimes`), with unpack200 and the headless AWT libraries: GPL-2.0 with the Classpath Exception. https://openjdk.org")
out.append("- **Caciocavallo** (`assets/components/caciocavallo*`): GPL-2.0 with the Classpath Exception. https://github.com/PojavLauncherTeam/caciocavallo")
out.append("- **authlib-injector** (`assets/components/auth_libs`): AGPL-3.0. https://github.com/yushijinhun/authlib-injector. The same folder holds **nide8auth** for NIDE8 sign-in servers (see https://login2.nide8.com).")
out.append("- **JNA** (`assets/runtimes/jna`, `libjnidispatch.so`): Apache-2.0 or LGPL-2.1. https://github.com/java-native-access/jna")
out.append("- Graphics: Mesa (Zink, Turnip/Freedreno, VirGL, OSMesa; MIT, see `assets/licenses/mesa-licenses.rst`), ANGLE (BSD-3-Clause), gl4es and NG-GL4ES (MIT), SPIRV-Cross (Apache-2.0), the Khronos timeline-semaphore Vulkan layer (Apache-2.0). Renderers added later as plugins (MobileGlues, for example) come with their own licences.")
out.append("- LWJGL 3.3.3 and 3.4.1 with its bundled libraries (BSD-3-Clause; their licences are in `assets/licenses/`), SDL3 and sdl2-compat (Zlib), OpenAL Soft (LGPL-2.0 or later), ByteHook (MIT), MMKV (BSD-3-Clause), SQLCipher (BSD-style), Flite speech synthesis (CMU Flite licence, BSD-style). https://github.com/festvox/flite")
out.append("- TextMate grammars and themes for the log viewer: see `assets/textmate/NOTICE.md`.\n")
out.append("## Libraries\n")
out.append("| Library | Copyright | Licence | Link |")
out.append("|---|---|---|---|")
for name, cp, lic, url in sorted(rows + [e for e in extra if e[0].lower() not in have], key=lambda r: r[0].lower()):
    out.append(f"| {name} | {cp or '—'} | {lic} | {url} |")
out.append("\nLicence texts bundled with the app are in `ZalithLauncher/src/main/res/raw/`. Minecraft is a trademark of Mojang Synergies AB; Voxelium includes no Minecraft game files.\n")
open(root + '/THIRD_PARTY_NOTICES.md', 'w', encoding='utf-8').write('\n'.join(out))
print(len(rows), 'from the in-app list,', len([e for e in extra if e[0].lower() not in have]), 'extra')
